    # Bind the exact query (in fixed parameter order) and the exact page
    # returned, so parameters, cursor or page content cannot be replayed
    # against an anchor they were never exported under.
    ordered_params = [params[field] for field in _PARAM_FIELDS]
    return hashlib.sha256(
        _compact([ordered_params, result])).hexdigest()


def _anchor_digest(manifest: list[list[Any]], log_digest: str,
                   head: str | None, scope: str, previous: str | None,
                   closed: bool) -> str:
    return hashlib.sha256(_compact(
        [manifest, log_digest, head, scope, previous, closed])).hexdigest()

